@Injectable()
export class AuthGuard implements CanActivate {
  constructor(private verifier: TokenVerifier, private reflector: Reflector) {}
  async canActivate(ctx: ExecutionContext): Promise<boolean> {
    if (this.reflector.getAllAndOverride<boolean>(IS_PUBLIC, [ctx.getHandler(), ctx.getClass()]))
      return true;                                                     // explicit public
    const req = ctx.switchToHttp().getRequest<Request>();
    const principal = await this.verifier.verify(req.headers.authorization); // delegated
    if (!principal) throw new UnauthorizedException();                 // challenge
    req.user = principal;                                              // request-scoped
    return true;
  }
}
